        if all(val // div == idx for lst, val, idx in examples):
            print(f"Rule: val // {div} == index")
    # Try sum of digits
    def sod(n):
        return sum(int(d) for d in str(n))
    if all(sod(val) % len(lst) == idx for lst, val, idx in examples):
